package com.fooddelivery.controller;
import com.fooddelivery.dto.OrderDtos.*; import com.fooddelivery.model.*; import com.fooddelivery.repository.*; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController { final OrderRepository orders; final UserRepository users; final RestaurantRepository restaurants; final MenuItemRepository menus; OrderController(OrderRepository o,UserRepository u,RestaurantRepository r,MenuItemRepository m){orders=o;users=u;restaurants=r;menus=m;} @PostMapping public Order create(@Valid @RequestBody OrderRequest r,Authentication a){var u=users.findByEmail(a.getName()).orElseThrow();var rest=restaurants.findById(r.restaurantId()).orElseThrow();var o=new Order();o.setUser(u);o.setRestaurant(rest);o.setDeliveryAddress(r.deliveryAddress());o.setPaymentMethod(r.paymentMethod());o.setStatus(OrderStatus.PREPARING);o.setOrderTime(LocalDateTime.now());BigDecimal total=BigDecimal.ZERO;for(var i:r.items()){var m=menus.findById(i.menuItemId()).orElseThrow();var oi=new OrderItem();oi.setOrder(o);oi.setMenuItem(m);oi.setQuantity(i.quantity());oi.setPrice(m.getPrice());o.getItems().add(oi);total=total.add(m.getPrice().multiply(BigDecimal.valueOf(i.quantity())));}o.setTotalAmount(total);o.setPaymentId("DEMO-"+UUID.randomUUID());return orders.save(o);} @GetMapping public List<OrderSummary> mine(Authentication a){return orders.findByUserOrderByOrderTimeDesc(users.findByEmail(a.getName()).orElseThrow()).stream().map(o->new OrderSummary(o.getId(),o.getRestaurant().getName(),o.getTotalAmount(),o.getStatus(),o.getOrderTime())).toList();} record OrderSummary(Long id,String restaurant,BigDecimal totalAmount,OrderStatus status,LocalDateTime orderTime){} }